    @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,com.fixmer.mared.technology.editor.GenesisEditorVisuals.bg());g.drawCenteredString(font,title,width/2,12,com.fixmer.mared.technology.editor.GenesisEditorVisuals.text());g.drawCenteredString(font,offer.getOrDefault("title","")+" · "+offer.getOrDefault("senderName131",""),width/2,34,com.fixmer.mared.technology.editor.GenesisEditorVisuals.dim());if(!"JOINED".equals(offer.get("kind131"))){var lines=new ArrayList<Component>();lines.add(WorkspaceScreen122.tr("role."+offer.get("role")));if(Boolean.parseBoolean(offer.getOrDefault("complex135","false")))for(String row:offer.getOrDefault("policy135","").split("\n"))lines.add(Component.literal(row));if(!offer.getOrDefault("prefix","").isEmpty())lines.add(Component.literal(offer.get("prefix")));var rights=new com.fixmer.genesis.technology.workspace.live122.WorkspaceRights131(offer);for(Capability cap:Capability.values())lines.add(Component.literal(rights.allows(cap)?"[x] ":"[ ] ").append(WorkspaceScreen122.tr("cap."+cap)));for(Panel panel:Panel.values())lines.add(Component.literal(rights.panel(panel)?"[x] ":"[ ] ").append(WorkspaceScreen122.tr("panel."+panel)));int x=Math.max(12,(width-680)/2),rows=Math.max(1,(height-130)/17);scroll=Math.min(scroll,Math.max(0,lines.size()-rows));for(int i=0;i<rows&&scroll+i<lines.size();i++)g.drawString(font,lines.get(scroll+i),x,65+i*17,com.fixmer.mared.technology.editor.GenesisEditorVisuals.text(),false);}super.render(g,mx,my,dt);}
